def initialize(pokemon, index, viewport = nil)
  super(viewport)
  @pokemon = pokemon
  @active = (index == 0)   # true = rounded panel, false = rectangular panel
  @refreshing = true
  self.x = (index % 2) * Graphics.width / 2
  self.y = (16 * (index % 2)) + (96 * (index / 2))
  @panelbgsprite = ChangelingSprite.new(0, 0, viewport)
  @panelbgsprite.z = self.z
  if @active   # Rounded panel
    @panelbgsprite.addBitmap("able", "Graphics/UI/Party/panel_round")
    @panelbgsprite.addBitmap("ablesel", "Graphics/UI/Party/panel_round_sel")
    @panelbgsprite.addBitmap("fainted", "Graphics/UI/Party/panel_round_faint")
    @panelbgsprite.addBitmap("faintedsel", "Graphics/UI/Party/panel_round_faint_sel")
    @panelbgsprite.addBitmap("swap", "Graphics/UI/Party/panel_round_swap")
    @panelbgsprite.addBitmap("swapsel", "Graphics/UI/Party/panel_round_swap_sel")
    @panelbgsprite.addBitmap("swapsel2", "Graphics/UI/Party/panel_round_swap_sel2")
  else   # Rectangular panel
    @panelbgsprite.addBitmap("able", "Graphics/UI/Party/panel_rect")
    @panelbgsprite.addBitmap("ablesel", "Graphics/UI/Party/panel_rect_sel")
    @panelbgsprite.addBitmap("fainted", "Graphics/UI/Party/panel_rect_faint")
    @panelbgsprite.addBitmap("faintedsel", "Graphics/UI/Party/panel_rect_faint_sel")
    @panelbgsprite.addBitmap("swap", "Graphics/UI/Party/panel_rect_swap")
    @panelbgsprite.addBitmap("swapsel", "Graphics/UI/Party/panel_rect_swap_sel")
    @panelbgsprite.addBitmap("swapsel2", "Graphics/UI/Party/panel_rect_swap_sel2")
  end
  @hpbgsprite = ChangelingSprite.new(0, 0, viewport)
  @hpbgsprite.z = self.z + 1
  @hpbgsprite.addBitmap("able", _INTL("Graphics/UI/Party/overlay_hp_back"))
  @hpbgsprite.addBitmap("fainted", _INTL("Graphics/UI/Party/overlay_hp_back_faint"))
  @hpbgsprite.addBitmap("swap", _INTL("Graphics/UI/Party/overlay_hp_back_swap"))
  @ballsprite = ChangelingSprite.new(0, 0, viewport)
  @ballsprite.z = self.z + 1
  @ballsprite.addBitmap("desel", "Graphics/UI/Party/icon_ball")
  @ballsprite.addBitmap("sel", "Graphics/UI/Party/icon_ball_sel")
  @pkmnsprite = PokemonIconSprite.new(pokemon, viewport)
  @pkmnsprite.setOffset(PictureOrigin::CENTER)
  @pkmnsprite.active = @active
  @pkmnsprite.z      = self.z + 2
  @helditemsprite = HeldItemIconSprite.new(0, 0, @pokemon, viewport)
  @helditemsprite.z = self.z + 3
  @overlaysprite = BitmapSprite.new(Graphics.width, Graphics.height, viewport)
  @overlaysprite.z = self.z + 4
  pbSetSystemFont(@overlaysprite.bitmap)
  @hpbar    = AnimatedBitmap.new("Graphics/UI/Party/overlay_hp")
  @statuses = AnimatedBitmap.new(_INTL("Graphics/UI/statuses"))
  @selected      = false
  @preselected   = false
  @switching     = false
  @text          = nil
  @refreshBitmap = true
  @refreshing    = false
  refresh
end

def pokemon=(value)
  @pokemon = value
  @pkmnsprite.pokemon = value if @pkmnsprite && !@pkmnsprite.disposed?
  @helditemsprite.pokemon = value if @helditemsprite && !@helditemsprite.disposed?
  @refreshBitmap = true
  refresh
end

def refresh
  return if disposed?
  return if @refreshing
  @refreshing = true
  refresh_panel_graphic
  refresh_hp_bar_graphic
  refresh_ball_graphic
  refresh_pokemon_icon
  refresh_held_item_icon
  if @overlaysprite && !@overlaysprite.disposed?
    @overlaysprite.x     = self.x
    @overlaysprite.y     = self.y
    @overlaysprite.color = self.color
  end
  refresh_overlay_information
  @refreshBitmap = false
  @refreshing = false
end

def pbHardRefresh
  @scene.pbHardRefresh
end

def pbRefresh
  @scene.pbRefresh
end

def pbRefreshSingle(i)
  @scene.pbRefreshSingle(i)
end

def pokemon=(value)
  @pokemon = value
  @animBitmap&.dispose
  @animBitmap = nil
  if !@pokemon
    self.bitmap = nil
    @current_frame = 0
    return
  end
  @animBitmap = AnimatedBitmap.new(GameData::Species.icon_filename_from_pokemon(value))
  self.bitmap = @animBitmap.bitmap
  self.src_rect.width  = @animBitmap.height
  self.src_rect.height = @animBitmap.height
  @frames_count = @animBitmap.width / @animBitmap.height
  @current_frame = 0 if @current_frame >= @frames_count
  changeOrigin
end

def self.icon_bitmap_from_pokemon(pkmn)
  return self.icon_bitmap(pkmn.species, pkmn.form, pkmn.gender, pkmn.shiny?, pkmn.shadowPokemon?, pkmn.egg?)
end

def self.icon_filename(species, form = 0, gender = 0, shiny = false, shadow = false, egg = false)
  return self.egg_icon_filename(species, form) if egg
  return self.check_graphic_file("Graphics/Pokemon/", species, form, gender, shiny, shadow, "Icons")
end

def self.sprite_bitmap(species, form = 0, gender = 0, shiny = false, shadow = false, back = false, egg = false)
  return self.egg_sprite_bitmap(species, form) if egg
  return self.back_sprite_bitmap(species, form, gender, shiny, shadow) if back
  return self.front_sprite_bitmap(species, form, gender, shiny, shadow)
end

def initialize(hash)
  @id                       = hash[:id]
  @real_name                = hash[:real_name]        || "Unnamed"
  @real_name_plural         = hash[:real_name_plural] || "Unnamed"
  @real_portion_name        = hash[:real_portion_name]
  @real_portion_name_plural = hash[:real_portion_name_plural]
  @pocket                   = hash[:pocket]           || 1
  @price                    = hash[:price]            || 0
  @sell_price               = hash[:sell_price]       || (@price / 2)
  @bp_price                 = hash[:bp_price]         || 1
  @field_use                = hash[:field_use]        || 0
  @battle_use               = hash[:battle_use]       || 0
  @flags                    = hash[:flags]            || []
  @consumable               = hash[:consumable]
  @consumable               = !is_important? if @consumable.nil?
  @show_quantity            = hash[:show_quantity]
  @move                     = hash[:move]
  @real_description         = hash[:real_description] || "???"
  @pbs_file_suffix          = hash[:pbs_file_suffix]  || ""
end

def has_flag?(flag)
  return @flags.any? { |f| f.downcase == flag.downcase }
end

def pbCheckUseOnPokemon(item, pkmn, _screen)
  return pkmn && !pkmn.egg? && (!pkmn.hyper_mode || GameData::Item.get(item)&.is_scent?)
end
